function spawn(boss=false){let a=Math.random()*Math.PI*2,r=Math.max(W,H)*.58+80;let f=factions[selected].enemy[Math.random()<.5?0:1];state.enemies.push({x:state.p.x+Math.cos(a)*r,y:state.p.y+Math.sin(a)*r,f,hp:boss?650:23+state.time*.22,max:boss?650:23+state.time*.22,speed:boss?38:28+Math.random()*20+state.time*.07,boss,hit:0,fire:1.4+Math.random()*2,charge:0})}
